import{_ as d,o as a,c as e,ai as r}from"./chunks/framework.C33Uq6m-.js";const u=JSON.parse('{"title":"成本面板","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/cost-dashboard.md","filePath":"zh/guide/cost-dashboard.md"}'),o={name:"zh/guide/cost-dashboard.md"};function l(n,t,i,s,h,c){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="成本面板" tabindex="-1">成本面板 <a class="header-anchor" href="#成本面板" aria-label="Permalink to &quot;成本面板&quot;">​</a></h1><p>成本面板统计你所有会话的 token 用量，并估算同样的工作量在商用云 API 上会花多少钱。</p><p><strong>侧边栏位置：</strong> 成本 <strong>路由：</strong> <code>/costs</code></p><h2 id="为什么要在本地跟踪成本" tabindex="-1">为什么要在本地跟踪成本？ <a class="header-anchor" href="#为什么要在本地跟踪成本" aria-label="Permalink to &quot;为什么要在本地跟踪成本？&quot;">​</a></h2><p>Ollama 在你自己的机器上运行，不花一分钱。但了解等价的云端成本有助于你：</p><ul><li><strong>量化节省</strong> —— 看清本地运行到底省下了多少</li><li><strong>规划容量</strong> —— 弄清哪些模型消耗的 token 最多</li><li><strong>比较效率</strong> —— 找出每个 token 产出最划算的模型</li></ul><h2 id="面板分区" tabindex="-1">面板分区 <a class="header-anchor" href="#面板分区" aria-label="Permalink to &quot;面板分区&quot;">​</a></h2><h3 id="概要卡片" tabindex="-1">概要卡片 <a class="header-anchor" href="#概要卡片" aria-label="Permalink to &quot;概要卡片&quot;">​</a></h3><p>顶部四张卡片显示：</p><ul><li><strong>总 token 数</strong> —— 所有会话中提示词 + 生成内容的 token 总和</li><li><strong>会话数</strong> —— 已记录的对话会话总数</li><li><strong>估算成本</strong> —— 同样的用量在云 API 上的花费</li><li><strong>每会话平均成本</strong> —— 每次会话的平均估算成本</li></ul><h3 id="按模型的-token-用量" tabindex="-1">按模型的 token 用量 <a class="header-anchor" href="#按模型的-token-用量" aria-label="Permalink to &quot;按模型的 token 用量&quot;">​</a></h3><p>一张横向堆叠柱状图，显示你用过的每个模型的提示词 token（靛蓝色）与生成 token（紫色）。模型按 token 总量排序。</p><h3 id="每日用量" tabindex="-1">每日用量 <a class="header-anchor" href="#每日用量" aria-label="Permalink to &quot;每日用量&quot;">​</a></h3><p>一张双轴折线图：</p><ul><li><strong>左轴</strong> —— 每日总 token 数（填充区域）</li><li><strong>右轴</strong> —— 每日估算成本（虚线）</li></ul><p>把鼠标悬停在任意点上可查看精确数值。</p><h3 id="模型明细表" tabindex="-1">模型明细表 <a class="header-anchor" href="#模型明细表" aria-label="Permalink to &quot;模型明细表&quot;">​</a></h3><p>一张详细表格，包含以下列：</p><table tabindex="0"><thead><tr><th>列</th><th>说明</th></tr></thead><tbody><tr><td>模型</td><td>Ollama 模型名称</td></tr><tr><td>会话数</td><td>对话会话数量</td></tr><tr><td>提示词</td><td>提示词 token 总数</td></tr><tr><td>生成</td><td>生成内容 token 总数</td></tr><tr><td>合计</td><td>token 总量</td></tr><tr><td>估算成本</td><td>等价云端成本的估算值</td></tr><tr><td>来源</td><td>定价数据的出处</td></tr></tbody></table><h2 id="定价数据" tabindex="-1">定价数据 <a class="header-anchor" href="#定价数据" aria-label="Permalink to &quot;定价数据&quot;">​</a></h2><p>定价基于常见模型系列的等价云 API 费率：</p><table tabindex="0"><thead><tr><th>模型系列</th><th>输入 $/百万</th><th>输出 $/百万</th><th>来源</th></tr></thead><tbody><tr><td>llama3.2</td><td>$0.04</td><td>$0.04</td><td>Together AI</td></tr><tr><td>llama3.1</td><td>$0.05</td><td>$0.08</td><td>Groq</td></tr><tr><td>gemma3</td><td>$0.10</td><td>$0.10</td><td>Google</td></tr><tr><td>mistral</td><td>$0.25</td><td>$0.25</td><td>Mistral</td></tr><tr><td>deepseek-r1</td><td>$0.55</td><td>$2.19</td><td>DeepSeek</td></tr><tr><td>phi4</td><td>$0.07</td><td>$0.14</td><td>Azure</td></tr><tr><td>qwen2.5</td><td>$0.15</td><td>$0.15</td><td>阿里巴巴</td></tr></tbody></table><p>不在定价表中的模型会回退到 $0.10/$0.10 每百万 token 的通用估算，并标注为「估算」。</p><div class="info custom-block"><p class="custom-block-title">这些都是估算值</p><p>页面显示的所有成本，都是同等用量在云 API 上的花费。Ollama 在本地运行不产生费用。定价数据是一份静态快照，可能与当前的云端价格不一致。</p></div><h2 id="数据来源" tabindex="-1">数据来源 <a class="header-anchor" href="#数据来源" aria-label="Permalink to &quot;数据来源&quot;">​</a></h2><p>成本面板的全部数据都来自指标存储 —— 也就是对话过程中记录的那些会话指标。不需要额外的跟踪或存储。成本存储是纯计算（响应式）的，有新会话记录时会自动重新计算。</p>',26)])])}const b=d(o,[["render",l]]);export{u as __pageData,b as default};
